83	// and must never become a label). The HANDOFF comment names the session and the
84	// invocation nonce. The EPISODE comment is the boundary the claim arbiter is
85	// scoped to: every claim before it is dead, and arbitrating over dead claims makes
86	// one outrank every future live claimant — the item then livelocks through reclaim
87	// cycles forever (F18). A reclaim, a revert and a hand re-queue each write one.
88	export const CLAIM_MARKER = '<!-- claudinite-claim -->';
89	export const HANDOFF_MARKER = '<!-- claudinite-handoff -->';
90	export const EPISODE_MARKER = '<!-- claudinite-episode -->';
91	
92	// --- the body -----------------------------------------------------------------
93	
94	export const NOT_BEFORE_FIELD = 'Not-before';
95	export const BLOCKED_BY_FIELD = 'Blocked-by';
96	
97	const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
98	const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;
99	
100	// Build a work item body. The first line is the task path — the only thing an
101	// executor reads to locate the worker, validated in code before anything trusts
102	// it. Everything behavior-defining (model, ceiling, worker content, prework
103	// command) is read from the tracked task files at HEAD, never from here.
104	export function workItemBody({
105	  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
106	}) {
107	  const lines = [taskPath, ''];
108	  const fields = [];
109	  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
110	  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
111	  if (fields.length) lines.push(...fields, '');
112	  lines.push('Execute the Claudinite task above.');
113	  if (context.length) {
114	    lines.push(
115	      'The Context section below is binding scope — do not re-decide it.',
116	      '',
117	      '### Context',
118	      ...context.map((c) => `- ${c}`),
119	    );
120	  }
121	  if (reason) lines.push('', '### Why the agent is here', '', `- ${reason}`);
122	  if (delivered.length) lines.push('', '### Delivered by prework', '', ...delivered.map((d) => `- ${d}`));
123	  return lines.join('\n') + '\n';
124	}
125	
126	// Parse an item body back into the facts the tick and the executor read. A body
127	// with no first line, or whose fields are absent, yields nulls — absence is
128	// meaningful everywhere here and is never filled in with a default.
129	export function parseWorkItemBody(body) {
130	  const text = String(body ?? '');
131	  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
132	  const nb = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
133	  const bb = BLOCKED_BY_RE.exec(text)?.[1] ?? '';
134	  const blockedBy = [...bb.matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
135	  return { taskPath, notBefore: nb, blockedBy };
136	}
137	
138	// Stamp (or clear) `Not-before` on an existing body, in place where the field is
139	// already present and directly under the task path otherwise. Text surgery rather
140	// than a rebuild: the body also carries the creating precondition's Context and
141	// prework's Delivered section, which belong to whoever wrote them.
142	export function withNotBefore(body, iso) {
143	  const text = String(body ?? '');
144	  if (NOT_BEFORE_RE.test(text)) {
145	    return iso
146	      ? text.replace(NOT_BEFORE_RE, `${NOT_BEFORE_FIELD}: ${iso}`)
147	      : text.replace(/^Not-before:[ \t]*.*\n?/m, '');
148	  }
149	  if (!iso) return text;
150	  const lines = text.split('\n');
151	  const at = lines.findIndex((l) => l.trim() !== '');
152	  if (at === -1) return `${NOT_BEFORE_FIELD}: ${iso}\n`;
153	  lines.splice(at + 1, 0, '', `${NOT_BEFORE_FIELD}: ${iso}`);
154	  return lines.join('\n');
155	}
156	
157	// Set a section of an item body (the Context, prework's Delivered, the agent's Why)
158	// — replacing one of the same heading if it is already there, appending otherwise.
159	//
160	// REPLACING IS THE WHOLE POINT, and appending was a live bug (#879). Every standing
161	// item is born carrying a `### Context`, and the hand-off writes Context again — so
162	// an append leaves TWO sections of that name, while the session is told to read "the
163	// issue's Context section", singular. The one it reads first is then the tick's birth
164	// note and the binding scope is in the other, which fails silently whichever section
165	// the agent picks. It also grows: an item re-queued through hand-off twice carried a
166	// third.
167	//
168	// A section runs to the next `### ` heading or to the end of the body, so a replaced
169	// section keeps its position rather than migrating to the bottom — the body stays in
170	// the order a reader learned it.
171	export function withSection(body, heading, lines) {
172	  if (!lines.length) return body;
173	  const text = String(body ?? '').replace(/\s*$/, '');
174	  const section = [`### ${heading}`, '', ...lines.map((l) => `- ${l}`)];
175	  const existing = text.split('\n');
176	  const at = existing.findIndex((l) => l.trim() === `### ${heading}`);
177	  if (at === -1) return `${text}\n\n${section.join('\n')}\n`;
178	  const after = existing.findIndex((l, i) => i > at && l.startsWith('### '));
179	  const tail = after === -1 ? [] : ['', ...existing.slice(after)];
180	  return `${[...existing.slice(0, at), ...section, ...tail].join('\n')}\n`;
181	}
