77	// deduped and sorted. Async because task discovery is; pure otherwise.
78	export async function declaredSecrets(root, config) {
79	  const { discoverTasks } = await import('./discover.mjs');
80	  const { tasks } = await discoverTasks(root, config);
81	  const names = tasks.flatMap((t) => t.decl?.required_secrets ?? []);
82	  // Endpoint tokens ride the same rail (tasks-dispatch DESIGN §12, §14.6): the
83	  // config maps an endpoint name to a URL and to the NAME of the Actions secret
84	  // holding its token, and the stamp puts that name in the executor's env exactly
85	  // as a `required_secrets` entry. The executor reads it only at the moment of the
86	  // invocation call; nothing else in a task's life ever sees it.
87	  const endpointTokens = Object.values(config?.taskScheduler?.endpoints ?? {})
88	    .map((e) => e?.tokenSecret).filter((n) => typeof n === 'string' && n);
