119	// GITHUB_TOKEN line, which is the same place it always was.
120	const SECRETS_MARKER = /^[ \t]*# claudinite:secrets\b.*$/m;
121	export function withDeclaredSecrets(stubText, names = []) {
122	  if (!names.length) return stubText;
123	  const lines = names.map((n) => `          ${n}: \${{ secrets.${n} }}`).join('\n');
