271	// the mount path and every cross-reference then spell.
272	export const packIdForRepo = (fullName) => (fullName ?? '').split('/').pop()
273	  .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
274	  .replace(/[^a-zA-Z0-9]+/g, '-')
275	  .toLowerCase()
276	  .replace(/^-+|-+$/g, '');
