2	// judgment or a longer horizon than the tick's hourly label mechanics. Four rules,
3	// pure, each returning the items it claims plus the comment it would post; the
4	// janitor task's worker is the only I/O shell over them.
5	//
6	// What is NOT here: the executing-leash reclaim, which rides the tick (a
7	// deterministic label rule, serialized and hourly, recovering a dead executor's
8	// item in ~2h instead of ~25h). That amends the single-recovery-site split in
9	// siting, not in principle — recovery still happens once, in one place per rule,
10	// in code, and never as a sweep inside a session that is executing something.
11	
12	import { periodMs } from './anchors.mjs';
13	import {
14	  READY, AGENT, BLOCKED, NEEDS_HUMAN, STATE_LABELS,
15	  parseWorkItemTitle, parseWorkItemBody, hasLabel, labelNames,
16	} from './work-item.mjs';
17	
18	export const AGENT_LEASH_MS = 3 * 3600e3;
19	export const STALE_READY_PERIODS = 2;
20	export const STUCK_BLOCKED_MS = 2 * 86400e3;
21	
22	const ms = (t) => (t == null ? null : new Date(t).getTime());
23	const idle = (item, now) => ms(now) - (ms(item.updated_at) ?? ms(item.created_at) ?? ms(now));
24	
25	// Rule A — STALE READY. An item no executor picked for ~2 of its own periods comes
26	// out of the queue as a human's problem. The period is read from the task's
27	// declared `frequency` at HEAD (no title parsing — that was the slot grammar); an
28	// item whose task is unknown falls back to a day.
29	export function staleReadyItems(open = [], now, { periodFor = () => null, factor = STALE_READY_PERIODS } = {}) {
30	  return open.filter((i) => {
31	    if (!hasLabel(i, READY) || hasLabel(i, NEEDS_HUMAN)) return false;
32	    const parsed = parseWorkItemTitle(i.title);
33	    if (!parsed) return false;
34	    const per = periodFor(`${parsed.pack}/${parsed.task}`) ?? 86400e3;
35	    // `readySince` is the item's last touch: every transition into ready is a
36	    // label write, so an item that has sat unread since then has not been touched.
37	    return idle(i, now) >= factor * per;
38	  });
39	}
40	
41	export const staleReadyComment = (item) => {
42	  const p = parseWorkItemTitle(item.title);
43	  return `This work item for ${p ? `${p.pack}/${p.task}` : 'this task'} has sat \`${READY}\` for over ~${STALE_READY_PERIODS} of its scheduling periods `
44	    + `without an executor picking it up. Labeling \`${NEEDS_HUMAN}\` and taking it out of the queue for triage.`;
45	};
46	
47	// Rule B — THE AGENT LEASH. `task:agent` silent past ~3h means the session died.
48	// The hand-off comment names which session, so the escalation can say so. The
49	// assumption is stated rather than discovered: a legitimately longer-running agent
50	// must comment on its item to reset the activity clock, or it is declared dead.
51	export function deadAgentItems(open = [], now, { leashMs = AGENT_LEASH_MS } = {}) {
52	  return open.filter((i) => hasLabel(i, AGENT) && !hasLabel(i, NEEDS_HUMAN) && idle(i, now) >= leashMs);
53	}
54	
55	export const deadAgentComment = (item, sessionNote = null) =>
56	  `This work item has carried \`${AGENT}\` for over ${Math.round(AGENT_LEASH_MS / 3600e3)}h with no activity — `
57	  + `the agent session that claimed it${sessionNote ? ` (${sessionNote})` : ''} never converged it. Labeling \`${NEEDS_HUMAN}\` for triage.`;
58	
59	// Rule C — THE STUCK-DEPENDENCY SWEEP (F14). The stale-ready rule cannot see this
60	// at all: a blocked item is never ready. So a blocked item whose blockers have not
61	// resolved past the bound gets an escalation COMMENT and nothing else — labels
62	// untouched, so the item still proceeds by itself the moment its blockers resolve,
63	// and a human who decides it is dead closes it by hand.
64	//
65	// Sleeping items (a future `Not-before`, blockers closed) never match: waiting for
66	// a time is the mechanism working.
67	export function stuckBlockedItems(open = [], now, { stateOf = () => null, boundMs = STUCK_BLOCKED_MS } = {}) {
68	  return open.filter((i) => {
69	    if (!hasLabel(i, BLOCKED) || hasLabel(i, NEEDS_HUMAN)) return false;
70	    const { blockedBy } = parseWorkItemBody(i.body);
71	    if (!blockedBy.length) return false;
72	    if (blockedBy.every((n) => stateOf(n) === 'closed')) return false;
73	    return ms(now) - ms(i.created_at) >= boundMs;
74	  });
75	}
76	
77	export const stuckBlockedComment = (item, unresolved) =>
78	  `This work item has been blocked on ${unresolved.map((n) => `#${n}`).join(', ')} for over `
79	  + `${Math.round(STUCK_BLOCKED_MS / 86400e3)} days. Nothing here is stuck mechanically — it will proceed by itself the moment those close — `
80	  + 'but if they are never going to, close this item by hand.';
81	
82	// Rule D — THE STATELESS-ITEM REPAIR. An open work item wearing neither a `task:*`
83	// state nor `needs-human` is off the state machine entirely: a torn label swap's
84	// leavings (an executor that died between the remove and the add), invisible to
85	// every rule that filters by state. It converges to triage — the same posture a
86	// malformed item gets.
87	export function statelessItems(open = []) {
88	  return open.filter((i) => {
89	    const names = labelNames(i);
90	    return !names.includes(NEEDS_HUMAN) && !STATE_LABELS.some((l) => names.includes(l));
91	  });
92	}
93	
94	export const statelessComment = () =>
95	  'This work item carries no state label at all — the leavings of a label swap that tore mid-flight, which puts it outside the state machine. '
96	  + `Labeling \`${NEEDS_HUMAN}\`: re-queue it by hand (remove \`${NEEDS_HUMAN}\`, add \`${READY}\`) once you have looked at it.`;
97	
98	// The period of a task, for rule A — read from the declaration at HEAD.
99	export const periodForTasks = (tasks = []) => {
100	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
101	  return (id) => periodMs(byId.get(id)?.decl?.frequency);
102	};
